CREATE SCHEMA IF NOT EXISTS messaging;

CREATE TABLE IF NOT EXISTS messaging.mails (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    mail_message_id UUID NOT NULL,
    state mail_state NOT NULL DEFAULT 'outgoing',
    failure_type mail_failure_type,
    scheduled_date TIMESTAMPTZ,
    auto_delete BOOLEAN NOT NULL DEFAULT FALSE,
    failure_reason TEXT,
    email_to TEXT,
    email_cc TEXT,
    reply_to TEXT,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS mail_state_scheduled_idx ON messaging.mails (state, scheduled_date);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_mails_metadata_gin ON messaging.mails USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_mails_metadata_deleted_at ON messaging.mails ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_mails_metadata_created_at ON messaging.mails ((metadata->>'created_at'));
CREATE INDEX IF NOT EXISTS idx_mails_metadata_updated_at ON messaging.mails ((metadata->>'updated_at'));

-- Triggers for automatic metadata timestamp management
-- Automatically sets created_at on INSERT and updated_at on UPDATE

-- Function to set metadata->'created_at' on INSERT
CREATE OR REPLACE FUNCTION messaging.mails_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS mails_insert_audit ON messaging.mails;
CREATE TRIGGER mails_insert_audit BEFORE INSERT ON messaging.mails
    FOR EACH ROW EXECUTE FUNCTION messaging.mails_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS mails_update_audit ON messaging.mails;
CREATE TRIGGER mails_update_audit BEFORE UPDATE ON messaging.mails
    FOR EACH ROW EXECUTE FUNCTION messaging.mails_audit_timestamp();
